self.KB_CONTENT["card:751572"]={"id":"card:751572","ty":"card","sourceId":"751572","title":"『自訂營運分類資料建立作業』中的『營運分類名稱(NL002)』為何？","ver":"iGP","topic":"分類","keywords":["分類","自訂","營運"],"y":"other","answer":"* 此欄位不可空白。* 可自行輸入名稱，亦可按(icon)或[F2]片語資料查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
