self.KB_CONTENT["field:757710"]={"id":"field:757710","ty":"field","sourceId":"757710","title":"供應廠商","ver":"iGP","topic":"","keywords":[],"job":"請購變更建立作業","code":"TV011","answer":"* [F2]廠商資料查詢，自動帶出該供應廠商之採購單位、幣別、課稅別相關資料。* [F3]品號廠商資料查詢。","file":"fields.jsonl"};
self.KB_CONTENT["field:753556"]={"id":"field:753556","ty":"field","sourceId":"753556","title":"本幣銷退金額","ver":"iGP","topic":"","keywords":[],"job":"銷退單建立作業","code":"TI037","answer":"* 由單身本幣未稅金額累計。","file":"fields.jsonl"};
self.KB_CONTENT["field:753448"]={"id":"field:753448","ty":"field","sourceId":"753448","title":"折扣率","ver":"iGP","topic":"","keywords":[],"job":"銷退單建立作業","code":"","answer":"折扣率* 此欄位僅作顯示。","file":"fields.jsonl"};
self.KB_CONTENT["field:755532"]={"id":"field:755532","ty":"field","sourceId":"755532","title":"預測數量","ver":"iGP","topic":"","keywords":[],"job":"銷售預測建立作業","code":"MF008","answer":"* 此欄位須大於等於零。* 輸入至截止日期的預測出貨數量。","file":"fields.jsonl"};
